SELECT analytics_budget_facts.expense_category, AVG(analytics_budget_facts.budget_variance_pct) AS budget_variance_pct FROM analytics_budget_facts WHERE analytics_budget_facts.year = 2023 AND analytics_budget_facts.month = 3 AND analytics_budget_facts.department = 'department_12' AND analytics_budget_facts.cost_center = 'cc_012' GROUP BY analytics_budget_facts.expense_category ORDER BY budget_variance_pct DESC, analytics_budget_facts.expense_category ASC LIMIT 12
